import type { Page } from './types';
import type { SiteContext } from './engine';
import type { SiteBuildResult } from './build';

export type PluginHook = 'onStart' | 'beforeBuild' | 'afterBuild' | 'onFile' | 'onEnd';

export interface PluginContext {
  contentDir: string;
  outputDir: string;
  templatesDir?: string;
  port?: number;
